    private Spinner spinner(String[] values,String selected,java.util.function.Consumer<String> action){Spinner s=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values){@Override public View getView(int p,View c,android.view.ViewGroup g){TextView v=(TextView)super.getView(p,c,g);v.setTextColor(FG);v.setPadding(dp(12),dp(12),dp(12),dp(12));return v;}};s.setAdapter(a);s.setSelection(Math.max(0,Arrays.asList(values).indexOf(selected)));s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){action.accept(values[n]);}});return s;}
    private void generatePlan(){brief=briefField.getText().toString().trim();if(brief.isEmpty()){toast("Add a brief first.");return;}if(takes.size()>0){new AlertDialog.Builder(this).setTitle("Replace shot plan?").setMessage("Your existing takes stay in Assemble. The new plan starts from shot one.").setPositiveButton("Replace plan",(d,w)->runPlanner()).setNegativeButton("Keep plan",null).show();}else runPlanner();}
    private void runPlanner(){speech.stopListening();speech.stop();save();if(!planner.isModelAvailable()){shots.clear();shots.addAll(DirectorEngine.plan(brief,style));planSource="Editable template · local LLM not installed";shotIndex=0;save();render();return;}setBusy(true);status.setText("Local model is creating your shot plan…");planner.generate(brief+(referenceSummary.isEmpty()?"":"\nReference sampled observations (approximate, no style inferred): "+referenceSummary),style,new LocalPlanner.Listener(){public void onPlan(List<Shot> p,long ms,String model){setBusy(false);shots.clear();shots.addAll(p);shotIndex=0;planSource="Local AI · "+model+" · "+String.format(Locale.US,"%.1fs",ms/1000.0);save();render();}public void onError(String error){setBusy(false);toast(error);status.setText("Local model unavailable. Keep your plan or use the starter.");new AlertDialog.Builder(MainActivity.this).setTitle("Keep creating").setMessage(error).setPositiveButton("Use starter plan",(d,w)->{shots.clear();shots.addAll(DirectorEngine.plan(brief,style));planSource="Editable template · AI failed";save();render();}).setNegativeButton("Keep current",null).show();}});}
    private void listenBrief(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},42);return;}status.setText("Listening locally… tap another screen to stop");speech.listen(new SpeechCoach.Listener(){public void onText(String t){brief=t;if(briefField!=null)briefField.setText(t);status.setText("Voice brief ready for your review");save();}public void onError(String e){status.setText(e);toast(e);}});}
    private void editShot(int i){Shot s=shots.get(i);LinearLayout form=column();form.setPadding(dp(20),dp(10),dp(20),dp(10));EditText name=input(s.title,"Title"),cue=input(s.instruction,"Direction"),caption=input(s.caption,"Manual caption"),duration=input(""+(s.targetDurationMs/1000),"Seconds");duration.setInputType(2);form.addView(name);form.addView(cue);form.addView(caption);form.addView(duration);new AlertDialog.Builder(this).setTitle("Your shot").setView(form).setPositiveButton("Save",(d,w)->{long seconds=6;try{seconds=Long.parseLong(duration.getText().toString());}catch(Exception ignored){}shots.set(i,new Shot(s.id,name.getText().toString(),cue.getText().toString(),caption.getText().toString(),Math.max(2,Math.min(60,seconds))*1000));save();render();}).setNegativeButton("Cancel",null).show();}
