    private void startShoot(){if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.CAMERA,Manifest.permission.RECORD_AUDIO},41);return;}cameraPlaceholder.setVisibility(View.GONE);startCamera();}
    private void startCamera(){if(live)return;if(capture!=null&&capture.isRecording()){toast("The previous take is still saving. Try again in a moment.");return;}if(capture!=null){capture.close();capture=null;}if(pose!=null){pose.close();pose=null;}session=true;speech.stopListening();pose=new PoseCoach((cue,count,latency)->runOnUiThread(()->{if(!session||tab!=1)return;if(capture!=null&&!capture.isRecording()&&!countdown){status.setText("On-device pose · "+count+" visible points · "+latency+" ms");framingView.setText(cue);if(voice&&SystemClock.elapsedRealtime()-lastCue>12000){lastCue=SystemClock.elapsedRealtime();speech.speak(cue);}}}));pose.setMode(style);pose.setEnabled(isPoseShot());capture=new CaptureController(this,preview,new CaptureController.Listener(){public void onReady(){live=true;desiredLens=capture.getLensFacing();save();if(captureAction!=null)captureAction.setText("Record · 3 sec");status.setText("Shoot active · "+speech.describeAudioRoute());if(!capture.isAnalysisAvailable())framingView.setText("Live pose analysis unavailable on this camera. Follow your shot cue and check the preview.");else if(!isPoseShot())framingView.setText("Person-framing advice is off for this object shot. Follow your scene cue.");if(sequenceActive)prepareSequenceShot();}public void onRecordingStarted(){countdown=false;speech.stop();recordStart=SystemClock.elapsedRealtime();timerView.setText("● Recording — cues quiet");handler.post(tick);}public void onRecordingFinished(Uri uri,long duration){handler.removeCallbacks(tick);if(pose!=null)pose.setEnabled(session&&isPoseShot());if(duration>300){Shot s=recordingShot!=null?recordingShot:shots.get(shotIndex);takes.add(new Take(uri,s.id,s.title,s.caption,duration));save();}timerView.setText("Take saved · "+String.format(Locale.US,"%.1f",duration/1000.0)+" sec");status.setText("Review your take in Assemble");if(reviewAfterSave){reviewAfterSave=false;switchTab(2);}else if(sequenceActive){if(shotIndex+1<shots.size()){shotIndex++;save();render();cameraPlaceholder.setVisibility(View.GONE);startCamera();}else{sequenceActive=false;session=false;switchTab(2);status.setText("Your shot sequence is ready to review.");}}}public void onError(String e){sequenceActive=false;countdown=false;handler.removeCallbacks(tick);live=false;if(captureAction!=null)captureAction.setText("Start camera");toast(e);status.setText(e);if(pose!=null)pose.setEnabled(session&&isPoseShot());if(reviewAfterSave){reviewAfterSave=false;switchTab(2);}}});capture.setLensFacing(desiredLens);capture.setAnalyzer(pose);capture.startPreview();}
    private final Runnable tick=new Runnable(){public void run(){if(capture==null||!capture.isRecording())return;long elapsed=SystemClock.elapsedRealtime()-recordStart;String recordingStatus=String.format(Locale.US,"● %.1fs / %ds · quiet on set",elapsed/1000.0,recordingShot.targetDurationMs/1000);timerView.setText(recordingStatus);status.setText(recordingStatus);if((autoStop||sequenceActive)&&elapsed>=recordingShot.targetDurationMs){capture.stopRecording();return;}handler.postDelayed(this,100);}};
    private boolean isPoseShot(){if(style.toLowerCase(Locale.ROOT).contains("product"))return false;String title=shots.get(shotIndex).title.toLowerCase(Locale.ROOT);return !title.contains("cutaway")&&!title.contains("world")&&!title.contains("detail")&&!title.contains("fabric")&&!title.contains("product")&&!title.contains("texture")&&!title.contains("sleeve");}
    private void startCountdown(){if(busy){toast("Wait for local processing to finish.");return;}if(!live||capture==null){toast("Start the shoot camera first.");return;}if(countdown||capture.isRecording())return;if(guideSequence&&!sequenceActive){sequenceActive=true;prepareSequenceShot();return;}speech.stop();speech.stopListening();pose.setEnabled(false);countdown=true;int generation=++countdownGeneration;recordingShot=shots.get(shotIndex);cueView.setText(recordingShot.instruction);count(3,generation);}
    private void prepareSequenceShot(){
        speech.stopListening();pose.setEnabled(false);countdown=true;
        int generation=++countdownGeneration;recordingShot=shots.get(shotIndex);
        cueView.setText(recordingShot.instruction);
        framingView.setText("Follow this direction. Your pose break starts after the cue.");
        status.setText("Direction first · Stop ends the sequence");timerView.setText("Hear your next scene");
        if(voice)speech.speakThen(recordingShot.instruction,()->beginPoseBreak(generation),()->spokenCueFailed(generation));
        else beginPoseBreak(generation);
    }
    private boolean countdownCurrent(int generation){return generation==countdownGeneration&&countdown&&session;}
    private void beginPoseBreak(int generation){
        if(!countdownCurrent(generation)||!sequenceActive)return;
        status.setText("Pose break · 8 seconds · Stop ends the sequence");timerView.setText("Get ready for your next take");
        handler.postDelayed(()->{if(countdownCurrent(generation)&&sequenceActive)count(3,generation);},8000);
    }
    private void spokenCueFailed(int generation){
        if(!countdownCurrent(generation))return;
        stopTake();
        timerView.setText("Paused before recording");
        status.setText("Offline voice unavailable. Turn spoken direction off to use the visual countdown.");
    }
    private void count(int n,int generation){
        if(!countdownCurrent(generation))return;
        if(n==0){speech.stop();capture.startRecording();return;}
        timerView.setText("Starting in "+n+"…");status.setText("Starting in "+n+"… tap Stop to cancel");
        long earliest=SystemClock.elapsedRealtime()+1000;
        if(voice)speech.speakThen(Integer.toString(n),()->{
            if(countdownCurrent(generation))handler.postDelayed(()->count(n-1,generation),Math.max(350,earliest-SystemClock.elapsedRealtime()));
        },()->spokenCueFailed(generation));
        else handler.postDelayed(()->count(n-1,generation),1000);
    }
    private void cancelCountdown(){countdown=false;++countdownGeneration;}
    private void stopTake(){sequenceActive=false;cancelCountdown();handler.removeCallbacks(tick);if(capture!=null)capture.stopRecording();speech.stopListening();speech.stop();if(pose!=null)pose.setEnabled(session&&isPoseShot());}
    private void editPage(){
        headline("Put your story together.","Choose takes, tighten the cuts, add your words.");LinearLayout c=card();c.addView(text("LOOK & FEEL",11,LIME));EditText title=input(reelTitle,"Optional reel title");title.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){reelTitle=s.toString();}public void afterTextChanged(android.text.Editable e){}});c.addView(title);c.addView(spinner(new String[]{"Clean","Warm","Cinematic","Auto balance"},look,s->{look=s;save();}));c.addView(text("Local presets or automatic neutral/exposure balance · vertical 720p · up to 12 cuts / 3 minutes. Originals stay intact. English speech can be transcribed offline.",12,MUTED));c.addView(button("Import clips from my phone",false,()->pickClips()));c.addView(button("Try synthetic demo clips",false,()->loadDemo()));content.addView(c);
        long total=0;for(int i=0;i<takes.size();i++){Take t=takes.get(i);final int index=i;if(t.selected)total+=t.outMs-t.inMs;LinearLayout row=card();CheckBox selected=new CheckBox(this);selected.setText(t.title);selected.setTextColor(FG);selected.setTextSize(19);selected.setChecked(t.selected);selected.setOnCheckedChangeListener((b,on)->{t.selected=on;save();updateSelectionSummary();});row.addView(selected);row.addView(text(String.format(Locale.US,"%.1f → %.1fs  ·  %s",t.inMs/1000.0,t.outMs/1000.0,t.caption.isEmpty()?"No caption":t.caption),13,MUTED));row.addView(button("Trim & typography",false,()->editTake(index)));row.addView(button("Generate offline subtitles",false,()->transcribeTake(index)));if(!t.subtitles.isEmpty()){row.addView(text(t.subtitles.size()+" timed subtitle drafts · review before export",12,LIME));row.addView(button("Review subtitle words & timing",false,()->reviewSubtitles(index)));}row.addView(button("Preview take",false,()->previewVideo(t.uri)));if(i>0)row.addView(button("Move earlier",false,()->{Collections.swap(takes,index,index-1);save();render();}));content.addView(row);}
        selectionSummary=text("",13,LIME);updateSelectionSummary();content.addView(selectionSummary);content.addView(button("Export my reel",true,()->export()));content.addView(button(pendingPack==null?"Save clips + edits for my laptop":"Save ready edit package",false,()->{if(pendingPack==null)packageProject();else requestPackDocument();}));if(pendingPack!=null)content.addView(button("Create a fresh edit package",false,()->packageProject()));content.addView(text("Portable ZIP includes the selected original clips and editable cut list. Choose a local folder; up to 512 MB of originals. Transfer through Office Kit separately.",12,MUTED));if(lastVideo!=null){content.addView(button("Play exported reel",false,()->previewVideo(lastVideo)));content.addView(button("Share reel",false,()->share(lastVideo,"video/mp4")));}if(lastEdit!=null){content.addView(button("Save editable cut list to Files",false,()->saveEditDocument()));content.addView(button("Share editable cut list",false,()->share(lastEdit,"application/json")));}
    }
    private void updateSelectionSummary(){if(selectionSummary==null)return;long total=0;int selected=0;for(Take take:takes)if(take.selected){total+=take.outMs-take.inMs;selected++;}selectionSummary.setText(selected+" selected / "+takes.size()+" takes · "+String.format(Locale.US,"%.1fs",total/1000.0)+" · up to 12 cuts / 3 min");}
    private void transcribeTake(int index){if(busy)return;if(!transcriber.isModelAvailable()){toast("Offline English speech model is not installed. Use manual text.");return;}Take take=takes.get(index);setBusy(true);status.setText("Listening to this clip locally… no microphone is opened");transcriber.transcribe(take.uri,new ClipTranscriber.Listener(){public void onComplete(List<SubtitleCue> cues,long ms){setBusy(false);take.subtitles=cues;take.captionOrigin="whisper-tiny.en-draft";save();render();status.setText(cues.isEmpty()?"No speech found. Add manual text if needed.":"Offline subtitle draft ready · "+String.format(Locale.US,"%.1fs",ms/1000.0)+" · review the words");if(!cues.isEmpty())reviewSubtitles(index);}public void onError(String e){setBusy(false);status.setText(e);toast(e);}});}
    private void reviewSubtitles(int index){Take take=takes.get(index);LinearLayout form=column();form.setPadding(dp(18),dp(8),dp(18),dp(8));ArrayList<EditText> words=new ArrayList<>(),starts=new ArrayList<>(),ends=new ArrayList<>();for(SubtitleCue cue:take.subtitles){form.addView(text("Source timestamps in seconds · short cues fit up to 4 lines",11,MUTED));EditText a=input(SubtitleTime.format(cue.startMs),"Start seconds"),b=input(SubtitleTime.format(cue.endMs),"End seconds"),w=input(cue.text,"Subtitle words");a.setInputType(8194);b.setInputType(8194);form.addView(a);form.addView(b);form.addView(w);starts.add(a);ends.add(b);words.add(w);}ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Review your subtitle draft").setView(scroll).setPositiveButton("Save reviewed subtitles",null).setNeutralButton("Remove subtitles",(d,w)->{take.subtitles.clear();take.captionOrigin="manual";save();render();}).setNegativeButton("Later",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{ArrayList<SubtitleCue> cues=new ArrayList<>();for(int i=0;i<words.size();i++){String w=words.get(i).getText().toString().trim();long start=SubtitleTime.parse(starts.get(i).getText().toString()),end=SubtitleTime.parse(ends.get(i).getText().toString());if(start<0||end<=start||end>take.durationMs)throw new IllegalArgumentException();if(!w.isEmpty())cues.add(new SubtitleCue(start,end,w));}take.subtitles=cues;take.captionOrigin="creator-reviewed-offline-asr";save();dialog.dismiss();render();}catch(Exception e){toast("Use valid subtitle times inside the source clip.");}}));dialog.show();}
    private void pickReference(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,52);}
    private void analyzeReference(Uri uri){try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}setBusy(true);status.setText("Inspecting selected frames locally…");references.analyze(uri,new ReferenceAnalyzer.Listener(){public void onResult(String summary,long elapsedMs){setBusy(false);referenceSummary=summary;save();tab=0;render();status.setText("Reference observations ready. Describe the trend's story, then build a plan.");}public void onError(String error){setBusy(false);status.setText(error);toast(error);}});}
    private void packageProject(){
        if(busy)return;
        discardPendingPack();setBusy(true);status.setText("Packing your selected originals and edits locally…");
        int generation=++saveGeneration;
        packager.export(takes,reelTitle,look,new ProjectPackager.Listener(){
            public void onProgress(long bytes){if(generation==saveGeneration)status.setText(String.format(Locale.US,"Packing originals locally · %.1f MB",bytes/1048576.0));}
            public void onComplete(File file,long bytes){
                if(generation!=saveGeneration){file.delete();return;}
                setBusy(false);pendingPack=file;save();
                if(getLifecycle().getCurrentState().isAtLeast(androidx.lifecycle.Lifecycle.State.RESUMED))requestPackDocument();
                else status.setText("Edit package ready. Return to Assemble to choose a save folder.");
            }
            public void onError(String message){if(generation!=saveGeneration)return;setBusy(false);status.setText(message);toast(message);}
        });
    }
    private void requestPackDocument(){
        if(pendingPack==null||!pendingPack.isFile()){discardPendingPack();toast("Create the package again before saving.");return;}
        if(!getLifecycle().getCurrentState().isAtLeast(androidx.lifecycle.Lifecycle.State.RESUMED))return;
        Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"MiniFilm-edit-package.zip");
        try{startActivityForResult(intent,54);}catch(Exception error){status.setText("Edit package is ready. Files could not open; try Save ready edit package again.");}
    }
    private void discardPendingPack(){if(pendingPack!=null){pendingPack.delete();pendingPack=null;save();}}
    private File restorePendingPack(String name){try{if(!name.matches("minifilm-pack-[0-9]+\\.zip"))return null;File file=new File(getCacheDir(),name);if(!file.getCanonicalFile().getParentFile().equals(getCacheDir().getCanonicalFile())||!file.isFile()||file.length()<=0||file.length()>ProjectPackager.MAX_ORIGINAL_BYTES+8388608L)return null;return file;}catch(Exception ignored){return null;}}
    @Override protected void onResume(){super.onResume();if(pendingPack!=null&&!busy&&tab==2){render();status.setText("Your previously prepared edit package is ready to save.");}}

    private void copyProjectPack(Uri destination){
        File source=pendingPack;pendingPack=null;save();if(source==null){toast("Create the package again before saving.");return;}
        int generation=++saveGeneration;savingDocument=true;setBusy(true);status.setText("Saving your portable edit package…");
        new Thread(()->{String error=null;try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(destination,"w")){
            if(out==null)throw new IOException();byte[] buffer=new byte[65536];int read;while((read=in.read(buffer))!=-1){if(generation!=saveGeneration)throw new IOException("Cancelled");out.write(buffer,0,read);}out.flush();
        }catch(Exception problem){error="Package save did not finish. The chosen document may be partial; save again with a new name. Original clips are safe.";}finally{source.delete();}
        String result=error;handler.post(()->{if(generation!=saveGeneration)return;savingDocument=false;setBusy(false);status.setText(result==null?"Clips + edits saved to your chosen folder. Office Kit transfer is ready to test.":result);if(result!=null)toast(result);});},"Save-edit-package").start();
    }
    private void saveEditDocument(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"MiniFilm-project.json");startActivityForResult(i,53);}
    private void copyEditDocument(Uri destination){Uri source=lastEdit;if(source==null)return;int generation=++saveGeneration;setBusy(true);savingDocument=true;status.setText("Saving your editable cut list…");new Thread(()->{String error=null;try(InputStream in=getContentResolver().openInputStream(source);OutputStream out=getContentResolver().openOutputStream(destination,"w")){if(in==null||out==null)throw new IOException();byte[] buffer=new byte[8192];int read;long count=0;while((read=in.read(buffer))!=-1){if(generation!=saveGeneration)throw new IOException("Cancelled");count+=read;if(count>1048576)throw new IOException();out.write(buffer,0,read);}out.flush();}catch(Exception e){error="Could not save the cut list. Choose a writable local folder and try again.";}final String result=error;handler.post(()->{if(generation!=saveGeneration)return;savingDocument=false;setBusy(false);status.setText(result==null?"Editable cut list saved to your chosen folder":result);if(result!=null)toast(result);});},"Save-cut-list").start();}
    private void pickClips(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,51);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==54){if(result==RESULT_OK&&data!=null&&data.getData()!=null)copyProjectPack(data.getData());else discardPendingPack();return;}if(request==53&&result==RESULT_OK&&data!=null&&data.getData()!=null){copyEditDocument(data.getData());return;}if(request==52&&result==RESULT_OK&&data!=null&&data.getData()!=null){analyzeReference(data.getData());return;}if(request!=51||result!=RESULT_OK||data==null)return;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());for(Uri u:uris){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(this,u);long duration=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration<=0||m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_VIDEO)==null)throw new IllegalArgumentException();takes.add(new Take(u,"import","Imported take "+(takes.size()+1),"",duration));}catch(Exception e){toast("That clip could not be read. Try a local MP4.");}finally{try{m.release();}catch(Exception ignored){}}}save();tab=2;render();}
    private void editTake(int i){Take t=takes.get(i);LinearLayout form=column();form.setPadding(dp(20),dp(10),dp(20),dp(10));EditText start=input(SubtitleTime.format(t.inMs),"In point / seconds"),end=input(SubtitleTime.format(t.outMs),"Out point / seconds"),caption=input(t.caption,"Typography (used when no subtitles)"),title=input(t.title,"Take title");start.setInputType(8194);end.setInputType(8194);form.addView(text("In / out in seconds · total "+SubtitleTime.format(t.durationMs)+"s",12,MUTED));form.addView(start);form.addView(end);form.addView(title);form.addView(caption);form.addView(text("Keep typography to 4 short lines. Longer text must be shortened before export. Take headings fit one line; omit the reel title for caption-only output.",12,MUTED));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Make this cut yours").setView(form).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{long in=SubtitleTime.parse(start.getText().toString()),out=SubtitleTime.parse(end.getText().toString());if(in<0||out<=in||out>t.durationMs||out-in<250)throw new IllegalArgumentException();t.inMs=in;t.outMs=out;t.title=title.getText().toString();t.caption=caption.getText().toString();save();dialog.dismiss();render();}catch(Exception e){toast("Use a valid cut at least 0.25 sec long within this take.");}}));dialog.show();}
    private void export(){if(busy)return;if(takes.stream().noneMatch(t->t.selected)){toast("Select at least one take.");return;}setBusy(true);if("Auto balance".equals(look)){status.setText("Inspecting local color samples… keep the app open");autoColor.analyze(takes,new AutoColorBalance.Listener(){public void onComplete(List<AutoColorBalance.Balance> balances,long elapsed){startReelExport(balances);}public void onError(String error){setBusy(false);status.setText(error);toast(error);}});}else startReelExport(Collections.emptyList());}
    private void startReelExport(List<AutoColorBalance.Balance> balances){status.setText("Exporting on your phone… keep the app open");exporter.export(takes,reelTitle,look,balances,new ReelExporter.Listener(){public void onProgress(int p){status.setText("Exporting locally · "+p+"%");}public void onComplete(Uri v,Uri e){setBusy(false);lastVideo=v;lastEdit=e;save();render();status.setText("Your reel is ready · saved to Movies / MiniFilm");}public void onError(String e){setBusy(false);status.setText(e);toast(e);}});}
    private void loadDemo(){if(busy)return;int generation=++demoGeneration;setBusy(true);status.setText("Creating synthetic demo clips locally…");DemoAssets.create(this,new DemoAssets.Listener(){public void onReady(List<Take> t){if(generation!=demoGeneration)return;setBusy(false);takes.addAll(t);tab=2;save();render();status.setText("Synthetic demo · no camera or microphone was used");}public void onError(String e){if(generation!=demoGeneration)return;setBusy(false);toast(e);status.setText(e);}});}
    private void previewVideo(Uri u){Uri safe=u;if("file".equals(u.getScheme()))safe=FileProvider.getUriForFile(this,"dev.minifilm.director.files",new File(u.getPath()));Intent i=new Intent(this,PreviewActivity.class).setData(safe).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(i);}catch(Exception e){toast("This video could not be opened.");}}
