    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    @Override public void onRequestPermissionsResult(int r,String[] p,int[] grants){super.onRequestPermissionsResult(r,p,grants);if(r==41){toast("Permissions updated. Tap Start camera when you're ready.");}else if(r==42)toast("Tap Speak my brief when you're ready.");}
    @Override protected void onStop(){super.onStop();sequenceActive=false;session=false;cancelCountdown();handler.removeCallbacks(tick);if(capture!=null)capture.stopPreview();speech.stop();speech.stopListening();if(pose!=null)pose.setEnabled(false);live=false;if(captureAction!=null)captureAction.setText("Start camera");save();}
    @Override protected void onDestroy(){++saveGeneration;++demoGeneration;if(capture!=null)capture.close();if(pose!=null)pose.close();speech.close();planner.close();transcriber.close();references.close();exporter.cancel();packager.close();autoColor.close();super.onDestroy();}
    private void save(){try{JSONObject o=new JSONObject();if(pendingPack!=null)o.put("pendingPack",pendingPack.getName());o.put("lens",desiredLens).put("guideSequence",guideSequence).put("reelTitle",reelTitle).put("referenceSummary",referenceSummary).put("brief",brief).put("style",style).put("look",look).put("source",planSource).put("shot",shotIndex).put("voice",voice);JSONArray ss=new JSONArray();for(Shot s:shots)ss.put(new JSONObject().put("id",s.id).put("title",s.title).put("cue",s.instruction).put("caption",s.caption).put("duration",s.targetDurationMs));o.put("shots",ss);JSONArray tt=new JSONArray();for(Take t:takes){JSONArray subs=new JSONArray();for(SubtitleCue cue:t.subtitles)subs.put(new JSONObject().put("start",cue.startMs).put("end",cue.endMs).put("text",cue.text));tt.put(new JSONObject().put("subtitles",subs).put("captionOrigin",t.captionOrigin).put("uri",t.uri.toString()).put("id",t.shotId).put("title",t.title).put("caption",t.caption).put("duration",t.durationMs).put("in",t.inMs).put("out",t.outMs).put("selected",t.selected));}o.put("takes",tt);if(lastVideo!=null)o.put("lastVideo",lastVideo.toString());if(lastEdit!=null)o.put("lastEdit",lastEdit.toString());getSharedPreferences("shoot",0).edit().putString("state",o.toString()).apply();}catch(Exception ignored){}}
    private void recoverTakes(){File dir=new File(getFilesDir(),"takes");File[] files=dir.listFiles((d,n)->n.endsWith(".mp4"));if(files==null)return;for(File f:files){Uri u=Uri.fromFile(f);if(takes.stream().anyMatch(t->t.uri.equals(u)))continue;MediaMetadataRetriever m=new MediaMetadataRetriever();try{m.setDataSource(f.getAbsolutePath());long duration=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION));if(duration>300)takes.add(new Take(u,"recovered","Recovered take","",duration));}catch(Exception ignored){}finally{try{m.release();}catch(Exception ignored){}}}}
    private void restore(){try{JSONObject o=new JSONObject(getSharedPreferences("shoot",0).getString("state","{}"));pendingPack=restorePendingPack(o.optString("pendingPack",""));desiredLens=o.optInt("lens",CameraSelector.LENS_FACING_FRONT);if(desiredLens!=CameraSelector.LENS_FACING_BACK)desiredLens=CameraSelector.LENS_FACING_FRONT;guideSequence=o.optBoolean("guideSequence",false);reelTitle=o.optString("reelTitle","");referenceSummary=o.optString("referenceSummary","");brief=o.optString("brief",brief);style=o.optString("style",style);look=o.optString("look",look);planSource=o.optString("source",planSource);shotIndex=o.optInt("shot",0);voice=o.optBoolean("voice",true);JSONArray ss=o.optJSONArray("shots");if(ss!=null)for(int i=0;i<ss.length();i++){JSONObject s=ss.getJSONObject(i);shots.add(new Shot(s.getString("id"),s.getString("title"),s.getString("cue"),s.getString("caption"),s.getLong("duration")));}JSONArray tt=o.optJSONArray("takes");if(tt!=null)for(int i=0;i<tt.length();i++){JSONObject t=tt.getJSONObject(i);Take a=new Take(Uri.parse(t.getString("uri")),t.getString("id"),t.getString("title"),t.getString("caption"),t.getLong("duration"));a.inMs=t.getLong("in");a.outMs=t.getLong("out");a.selected=t.getBoolean("selected");a.captionOrigin=t.optString("captionOrigin","manual");JSONArray cues=t.optJSONArray("subtitles");if(cues!=null)for(int j=0;j<cues.length();j++){JSONObject cue=cues.getJSONObject(j);a.subtitles.add(new SubtitleCue(cue.getLong("start"),cue.getLong("end"),cue.getString("text")));}takes.add(a);}if(o.has("lastVideo"))lastVideo=Uri.parse(o.getString("lastVideo"));if(o.has("lastEdit"))lastEdit=Uri.parse(o.getString("lastEdit"));}catch(Exception ignored){}}
